lines = title.strip().split("\n")
# find the minimum index of non-empty braille characters in all lines to strip it.
import re
min_idx = 9999
for line in lines:
  if line.strip():
    # Find first non-empty braille space `⠀`
    match = re.search(r'[^⠀\s]', line)
    if match:
      min_idx = min(min_idx, match.start())

formatted = []
for line in lines:
  # some lines might be empty or shorter
  l = line[min_idx:] if len(line) > min_idx else ""
  # truncate right space
  l = l.rstrip()
  formatted.append(f"  '{l}',")

with open(r'c:\AIagent\aegis-core\scratch\title.txt', 'w', encoding='utf-8') as f:
  f.write('\n'.join(formatted))
